'use strict';

const _ = require('lodash');
const BbPromise = require('bluebird');

module.exports = {
  mergeCustomProviderResources() {
    if (this.serverless.service.resources && !this.serverless.service.resources.Resources) {
      this.serverless.service.resources.Resources = {};
    }
    if (this.serverless.service.resources && !this.serverless.service.resources.Outputs) {
      this.serverless.service.resources.Outputs = {};
    }

    const compiledTemplate = this.serverless.service.provider.compiledCloudFormationTemplate;

    _.merge(compiledTemplate, this.serverless.service.resources);

    const resources = compiledTemplate.Resources;
    const deploymentLogicalId = _.findKey(resources, {
      Type: 'AWS::ApiGateway::Deployment',
    });

    if (deploymentLogicalId) {
      const deploymentRestApiId = _.get(resources, [
        deploymentLogicalId,
        'Properties',
        'RestApiId',
      ]);

      _.forEach(resources, (resource) => {
        if (resource.Type !== 'AWS::ApiGateway::BasePathMapping' ||
          !_.isEqual(_.get(resource, 'Properties.RestApiId'), deploymentRestApiId)) {
          return;
        }

        const dependsOn = [].concat(resource.DependsOn || []);
        if (!_.includes(dependsOn, deploymentLogicalId)) {
          resource.DependsOn = dependsOn.length
            ? dependsOn.concat(deploymentLogicalId)
            : deploymentLogicalId;
        }
      });
    }

    return BbPromise.resolve();
  },
};

